using ContentOS.Application;
using ContentOS.Contracts;
using ContentOS.Domain;
using ContentOS.Infrastructure;
using ContentOS.Integrations;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace ContentOS.Foundation.Tests;

[Collection("SQL runtime")]
[Trait("Category", "Sql")]
public sealed class SqlSocialTests
{
    [SqlFact]
    public async Task Four_destination_packages_preserve_core_revision_and_real_approved_media()
    {
        using var root = SocialTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s, actor: "m18-four"); var w = s.GetRequiredService<IWatchFactory>(); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, WatchTestFixture.Request(f), default); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Review", p.State); await w.ReviewAsync(f.Context.Owner, f.Context.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Approve", "Fixture", "fixture:render-quality-only", [], 1), default);
        var g = new RegistryTestFixture.Fixture(f.Context.Owner, f.Context.Universe, f.Context.Audience, f.Context.Bible, f.Context.Episode); var media = s.GetRequiredService<IMediaLibrary>(); var second = await media.ImportAsync(f.Context.Owner, f.Context.Universe, MediaTestFixture.Upload(g, f.Character, "slide-two", MediaFiles.ReferenceCard("second", [])), default); await MediaTestFixture.Review(s, g, second);
        var db = s.GetRequiredService<CoreDbContext>(); var before = await db.Revisions.AsNoTracking().SingleAsync(x => x.Id == f.Script.RevisionId); var all = new List<SocialPackageView>();
        foreach (var platform in new[] { "YouTube", "Instagram", "Facebook", "X" }) { var account = await SocialTestFixture.Account(s, f.Context, platform, key: platform.ToLowerInvariant()); all.Add(await SocialTestFixture.Package(s, f.Context, f.Script, account, platform, platform switch { "YouTube" => "Short", "Instagram" => "Carousel", "Facebook" => "Article", _ => "Link" }, platform == "Instagram" ? [f.Image.Id, second.Id] : platform == "YouTube" ? [f.Image.Id] : [], platform == "YouTube" ? p.Id : null)); }
        foreach (var package in all) { var export = await s.GetRequiredService<ISocialPublishing>().ExportAsync(f.Context.Owner, f.Context.Universe, package.Id, default); Assert.Equal(f.Script.RevisionId, export.Package.Snapshot!.Payload.RevisionId); Assert.Equal("ExportOnly;NotPublished", export.Status); }
        Assert.Equal(4, all.Select(x => x.PayloadHash).Distinct().Count()); Assert.Equal(before.Body, (await db.Revisions.AsNoTracking().SingleAsync(x => x.Id == before.Id)).Body); Assert.Equal("Thumbnail", all[0].Snapshot!.Payload.Media.Single(x => x.Kind == "Image").Role); Assert.Equal(2, all[1].Snapshot!.Payload.Slides.Length); Assert.All(await s.GetRequiredService<ISocialPublishing>().PublicationsAsync(f.Context.Owner, f.Context.Universe, default), x => Assert.Equal("Draft", x.State));
    }
    [SqlFact]
    public async Task Unknown_reconciles_original_vendor_account_after_switch_and_callbacks_cannot_duplicate_or_rebind()
    {
        using var root = SocialTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await EditorialTestFixture.Setup(s, "m18-unknown"); var e = s.GetRequiredService<IEditorialWorkbench>(); var content = await EditorialTestFixture.Approved(s, f, await e.StartAsync(f.Owner, f.Universe, EditorialTestFixture.Request(f), default)); var a = await SocialTestFixture.Account(s, f, adapter: "social.unknown.v1"); var pkg = await SocialTestFixture.Package(s, f, content, a); var social = s.GetRequiredService<ISocialPublishing>(); var request = new ScheduleSocial(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "India Standard Time"); var publication = await social.ScheduleAsync(f.Owner, f.Universe, request, default); publication = await SocialTestFixture.Drain(s, f, publication.Id); Assert.Equal("Unknown", publication.State); await SocialTestFixture.Account(s, f, adapter: "social.fixture.b.v1", version: 2); Assert.Equal(publication.Id, (await social.ScheduleAsync(f.Owner, f.Universe, request, default)).Id); await Assert.ThrowsAsync<RuntimeValidationException>(() => social.ControlAsync(f.Owner, f.Universe, publication.Id, new(Guid.NewGuid(), publication.RowVersion, "Resume", "fixture:no-blind-retry"), default));
        var reconcile = new SocialControl(Guid.NewGuid(), publication.RowVersion, "Reconcile", "fixture:original"); await social.ControlAsync(f.Owner, f.Universe, publication.Id, reconcile, default); await social.ControlAsync(f.Owner, f.Universe, publication.Id, reconcile, default); publication = (await social.PublicationsAsync(f.Owner, f.Universe, default)).Single(); Assert.Equal("Published", publication.State); Assert.Equal("social.unknown.v1", publication.Adapter); Assert.Equal("fixture:x", publication.AccountReference);
        var receipt = new SocialReceipt(Guid.NewGuid(), "fixture-event", publication.Platform, publication.AccountReference, publication.Adapter, pkg.PayloadHash, publication.RemoteId!, publication.RemoteUrl!, "fixture:original-ledger"); await social.ReceiptAsync(f.Owner, f.Universe, publication.Id, receipt, default); await social.ReceiptAsync(f.Owner, f.Universe, publication.Id, receipt with { OperationId = Guid.NewGuid() }, default); await Assert.ThrowsAsync<RuntimeConflictException>(() => social.ReceiptAsync(f.Owner, f.Universe, publication.Id, receipt with { OperationId = Guid.NewGuid(), EventId = "bad", AccountReference = "fixture:elsewhere" }, default));
        var db = s.GetRequiredService<CoreDbContext>(); Assert.Equal(1, await db.SocialEffects.CountAsync(x => x.PublicationId == publication.Id)); Assert.Equal(1, await db.SocialCallbacks.CountAsync(x => x.PublicationId == publication.Id)); Assert.Equal(1, await db.EditorialCopies.CountAsync(x => x.ItemId == content.Id)); Assert.NotEmpty(await social.NotificationsAsync(f.Owner, f.Universe, default));
    }
    [SqlFact]
    public async Task Approval_changes_and_revoked_account_block_scheduled_dispatch_without_side_effect()
    {
        using var root = SocialTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await EditorialTestFixture.Setup(s, "m18-fences"); var e = s.GetRequiredService<IEditorialWorkbench>(); var content = await EditorialTestFixture.Approved(s, f, await e.StartAsync(f.Owner, f.Universe, EditorialTestFixture.Request(f), default)); var social = s.GetRequiredService<ISocialPublishing>(); var a = await SocialTestFixture.Account(s, f); var pkg = await SocialTestFixture.Package(s, f, content, a); var pub = await social.ScheduleAsync(f.Owner, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default); await e.EditAsync(f.Owner, f.Universe, content.Id, new(Guid.NewGuid(), content.RowVersion, content.Current!.Title, "Changed original body", "Fiction", "Owned", "fixture:changed"), default); pub = await SocialTestFixture.Drain(s, f, pub.Id); Assert.Equal("Failed", pub.State); Assert.Null((await social.PackagesAsync(f.Owner, f.Universe, default)).Single(x => x.Id == pkg.Id).Snapshot); await Assert.ThrowsAsync<EvidenceBlockedException>(() => social.ExportAsync(f.Owner, f.Universe, pkg.Id, default));
        content = await EditorialTestFixture.Approved(s, f, await e.InspectAsync(f.Owner, f.Universe, content.Id, default)); pkg = await SocialTestFixture.Package(s, f, content, a, "after-edit"); pub = await social.ScheduleAsync(f.Owner, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default); var account = (await social.AccountsAsync(f.Owner, f.Universe, default)).Single(); await social.ControlAccountAsync(f.Owner, f.Universe, a, new(Guid.NewGuid(), account.RowVersion, "Revoke", "manual:local-revoke"), default); pub = await SocialTestFixture.Drain(s, f, pub.Id); Assert.Equal("Failed", pub.State); Assert.Equal(0, await s.GetRequiredService<CoreDbContext>().SocialEffects.CountAsync(x => x.TenantId == f.Owner.TenantId));
    }
    [SqlFact]
    public async Task Tenant_authorization_exact_hash_scope_and_export_only_release_gates_are_enforced()
    {
        using var root = SocialTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await EditorialTestFixture.Setup(s, "m18-access"); var e = s.GetRequiredService<IEditorialWorkbench>(); var content = await EditorialTestFixture.Approved(s, f, await e.StartAsync(f.Owner, f.Universe, EditorialTestFixture.Request(f), default)); var social = s.GetRequiredService<ISocialPublishing>(); var c = SocialChannelProfiles.Catalog.Single(x => x.Platform == "Facebook"); var account = await social.RegisterAccountAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "manual", 1, "Facebook", "owned-page", "manual.export.v1", "ExportOnly", c.Key, [], null, "manual:declared-account-not-connected"), default); var pkg = await social.PrepareAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "manual", content.Id, account, "Article", "campaign", "", "", []), default);
        await Assert.ThrowsAsync<CoreAccessException>(() => social.ReviewAsync(new(f.Owner.TenantId, "m13-author"), f.Universe, pkg.Id, new(Guid.NewGuid(), pkg.RowVersion, pkg.PayloadHash, "Approve", "Fixture", "fixture:unauthorized"), default)); await Assert.ThrowsAsync<EvidenceBlockedException>(() => social.ReviewAsync(f.Owner, f.Universe, pkg.Id, new(Guid.NewGuid(), pkg.RowVersion, "wrong", "Approve", "Fixture", "fixture:wrong-hash"), default)); await social.ReviewAsync(f.Owner, f.Universe, pkg.Id, new(Guid.NewGuid(), pkg.RowVersion, pkg.PayloadHash, "Approve", "Manual", "manual:package-only-not-core-public-release"), default);
        await Assert.ThrowsAsync<CoreAccessException>(() => social.ScheduleAsync(new(f.Owner.TenantId, "m13-author"), f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default)); await Assert.ThrowsAsync<CoreAccessException>(() => social.ExportAsync(new(Guid.NewGuid(), f.Owner.Actor), f.Universe, pkg.Id, default)); var pub = await social.ScheduleAsync(f.Owner, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default); await social.ProcessNextAsync(default); pub = (await social.PublicationsAsync(f.Owner, f.Universe, default)).Single(); Assert.Equal("Scheduled", pub.State); Assert.False((await social.AccountsAsync(f.Owner, f.Universe, default)).Single().Qualified); await Assert.ThrowsAsync<EvidenceBlockedException>(() => social.ReceiptAsync(f.Owner, f.Universe, pub.Id, new(Guid.NewGuid(), "manual-event", "Facebook", "owned-page", "manual.export.v1", pkg.PayloadHash, "123", "https://www.facebook.com/123", "manual:record"), default)); await social.ControlAsync(f.Owner, f.Universe, pub.Id, new(Guid.NewGuid(), pub.RowVersion, "Withdraw", "manual:cleanup"), default);
        await Assert.ThrowsAsync<RuntimeValidationException>(() => social.RegisterAccountAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "fake-live", 1, "Facebook", "owned", "manual.export.v1", "LiveSandboxVerified", c.Key, c.RequiredScopes, null, "manual:cannot-fabricate-qualification"), default));
    }
    [SqlFact]
    public async Task Confirmed_rate_limits_defer_but_unknown_never_auto_retries_and_destination_cannot_change_in_place()
    {
        using var root = SocialTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await EditorialTestFixture.Setup(s, "m18-rate"); var e = s.GetRequiredService<IEditorialWorkbench>(); var content = await EditorialTestFixture.Approved(s, f, await e.StartAsync(f.Owner, f.Universe, EditorialTestFixture.Request(f), default)); var a = await SocialTestFixture.Account(s, f, adapter: "social.rate-limit.v1"); var pkg = await SocialTestFixture.Package(s, f, content, a); var social = s.GetRequiredService<ISocialPublishing>(); var pub = await social.ScheduleAsync(f.Owner, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC", MaxAttempts: 2), default); await social.ProcessNextAsync(default); pub = (await social.PublicationsAsync(f.Owner, f.Universe, default)).Single(); Assert.Equal("Scheduled", pub.State); Assert.Equal("ConfirmedNotSubmittedRateLimit", pub.Outcome); Assert.Equal(1, pub.Attempts); await social.ControlAsync(f.Owner, f.Universe, pub.Id, new(Guid.NewGuid(), pub.RowVersion, "Withdraw", "fixture:rate-cleanup"), default); var binding = (await social.AccountsAsync(f.Owner, f.Universe, default)).Single().Binding; await Assert.ThrowsAsync<RuntimeConflictException>(() => social.RegisterAccountAsync(f.Owner, f.Universe, binding with { OperationId = Guid.NewGuid(), Version = 2, AccountReference = "fixture:different-destination" }, default)); Assert.Empty(await s.GetRequiredService<CoreDbContext>().SocialEffects.Where(x => x.TenantId == f.Owner.TenantId).ToArrayAsync());
    }
    [SqlFact]
    public async Task Expired_tokens_missing_scopes_and_role_escalation_block_while_publisher_can_schedule_reviewed_fixture()
    {
        using var root = SocialTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await EditorialTestFixture.Setup(s, "m18-lifecycle"); var e = s.GetRequiredService<IEditorialWorkbench>(); var content = await EditorialTestFixture.Approved(s, f, await e.StartAsync(f.Owner, f.Universe, EditorialTestFixture.Request(f), default)); var social = s.GetRequiredService<ISocialPublishing>(); var c = SocialChannelProfiles.Capability("x.export.v1"); var request = new RegisterSocialAccount(Guid.NewGuid(), "expired", 1, "X", "fixture:x", "social.fixture.a.v1", "Fixture", c.Key, c.RequiredScopes, DateTimeOffset.UtcNow.AddMinutes(-1), "fixture:expired"); var expired = await social.RegisterAccountAsync(f.Owner, f.Universe, request, default); var pkg = await SocialTestFixture.Package(s, f, content, expired, "expired"); await Assert.ThrowsAsync<EvidenceBlockedException>(() => social.ScheduleAsync(f.Owner, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default)); Assert.Equal("Expired", (await social.AccountsAsync(f.Owner, f.Universe, default)).Single(x => x.Id == expired).TokenState);
        var limited = await social.RegisterAccountAsync(f.Owner, f.Universe, request with { OperationId = Guid.NewGuid(), Key = "no-scopes", TokenExpiresUtc = null, AuthorizedScopes = [] }, default); pkg = await SocialTestFixture.Package(s, f, content, limited, "no-scopes"); await Assert.ThrowsAsync<EvidenceBlockedException>(() => social.ScheduleAsync(f.Owner, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default)); var account = await SocialTestFixture.Account(s, f); pkg = await SocialTestFixture.Package(s, f, content, account, "publisher"); var publisher = new CoreScope(f.Owner.TenantId, "m13-publisher"); await Assert.ThrowsAsync<CoreAccessException>(() => social.RegisterAccountAsync(publisher, f.Universe, request with { OperationId = Guid.NewGuid(), Key = "not-admin" }, default)); var pub = await social.ScheduleAsync(publisher, f.Universe, new(Guid.NewGuid(), pkg.Id, DateTimeOffset.UtcNow, "UTC"), default); pub = await SocialTestFixture.Drain(s, f, pub.Id); Assert.Equal("Published", pub.State); Assert.Equal("Fixture", pub.Mode); await Assert.ThrowsAsync<CoreAccessException>(() => s.GetRequiredService<ISourceRightsGuard>().CheckAsync(publisher, content.RevisionId, new("Generate", "en-IN", "IN", "Text"), default)); await Assert.ThrowsAsync<EvidenceBlockedException>(() => s.GetRequiredService<ISourceRightsGuard>().CheckAsync(publisher, content.RevisionId, new("Publish", "en-IN", "IN", "Text"), default));
    }
